/* Authentication and persistence are handled by member_server.py, never by localStorage passwords. */
window.WildRideLocalMember=(()=>{let csrf='',member=null,pendingSession=null;async function readSession(){const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error('會員服務未啟動，請使用會員網站啟動入口。');const data=await response.json();csrf=data.csrf;member=data.member;return data}function session(){if(!pendingSession)pendingSession=readSession().finally(()=>{pendingSession=null});return pendingSession}async function request(path,data){if(!csrf)await session();const response=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await response.json()}catch{throw Error('會員服務未回應，請確認網站服務已啟動。')}if(!response.ok){const error=Error(result.error||'操作失敗，請稍後再試。');error.status=response.status;throw error}if(result.csrf)csrf=result.csrf;if(Object.hasOwn(result,'member'))member=result.member;return result}return{session,request,get member(){return member}}})();
